resource "aws_vpc" "this" {
  cidr_block           = "{{vpc_cidr}}"
  enable_dns_hostnames = true
  enable_dns_support   = true
  tags = { Name = "{{vpc_name}}" }
}

resource "aws_internet_gateway" "this" {
  vpc_id = aws_vpc.this.id
  tags   = { Name = "{{vpc_name}}-igw" }
}

resource "aws_subnet" "public_a" {
  vpc_id                  = aws_vpc.this.id
  cidr_block              = "{{public_cidr_a}}"
  availability_zone       = "{{az_a}}"
  map_public_ip_on_launch = true
  tags = { Name = "{{vpc_name}}-public-a" }
}

resource "aws_subnet" "public_b" {
  vpc_id                  = aws_vpc.this.id
  cidr_block              = "{{public_cidr_b}}"
  availability_zone       = "{{az_b}}"
  map_public_ip_on_launch = true
  tags = { Name = "{{vpc_name}}-public-b" }
}

resource "aws_subnet" "private_a" {
  vpc_id            = aws_vpc.this.id
  cidr_block        = "{{private_cidr_a}}"
  availability_zone = "{{az_a}}"
  tags = { Name = "{{vpc_name}}-private-a" }
}

resource "aws_subnet" "private_b" {
  vpc_id            = aws_vpc.this.id
  cidr_block        = "{{private_cidr_b}}"
  availability_zone = "{{az_b}}"
  tags = { Name = "{{vpc_name}}-private-b" }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.this.id
  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.this.id
  }
}

resource "aws_route_table_association" "pub_a" {
  subnet_id      = aws_subnet.public_a.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "pub_b" {
  subnet_id      = aws_subnet.public_b.id
  route_table_id = aws_route_table.public.id
}
